using System.IO;
using UnityEditor;
using UnityEditor.Build.Reporting;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;

namespace CASCADE.EditorTools
{
    /// <summary>
    /// Batch entry points. Everything in the project is regenerated by these; no manual editor step exists.
    ///   CASCADE.EditorTools.BatchTools.RebuildAll   pipeline + assets + Main.unity
    ///   CASCADE.EditorTools.BatchTools.BuildDev     development player -> Builds/Dev/CASCADE.exe
    ///   CASCADE.EditorTools.BatchTools.BuildRelease release player     -> Builds/CASCADE/CASCADE.exe
    /// </summary>
    public static class BatchTools
    {
        public const string ScenePath = "Assets/_Game/Scenes/Main.unity";

        [MenuItem("Tools/CASCADE/Rebuild All")]
        public static void RebuildAll()
        {
            try
            {
                HdrpSetup.Run();
                ConfigurePlayer();
                var ga = AssetFactory.BuildAll();
                AssetFactory.CheckShaders();
                BuildScene(ga);
                AssetDatabase.SaveAssets();
                Debug.Log("CASCADE_OK RebuildAll");
            }
            catch (System.Exception e)
            {
                Debug.LogError("CASCADE_FAIL RebuildAll: " + e);
                if (Application.isBatchMode) EditorApplication.Exit(1);
            }
        }

        static void ConfigurePlayer()
        {
            PlayerSettings.productName = "CASCADE";
            PlayerSettings.companyName = "CASCADE";
            PlayerSettings.defaultScreenWidth = 1920;
            PlayerSettings.defaultScreenHeight = 1080;
            PlayerSettings.fullScreenMode = FullScreenMode.Windowed;
            PlayerSettings.resizableWindow = true;
            PlayerSettings.runInBackground = true;
            PlayerSettings.visibleInBackground = true;
            PlayerSettings.usePlayerLog = true;
            PlayerSettings.forceSingleInstance = false;
            PlayerSettings.SplashScreen.show = false;
            PlayerSettings.SplashScreen.showUnityLogo = false;
            PlayerSettings.SetUseDefaultGraphicsAPIs(BuildTarget.StandaloneWindows64, false);
            PlayerSettings.SetGraphicsAPIs(BuildTarget.StandaloneWindows64, new[] { GraphicsDeviceType.Direct3D11 });
            PlayerSettings.SetScriptingBackend(UnityEditor.Build.NamedBuildTarget.Standalone, ScriptingImplementation.Mono2x);
            PlayerSettings.gcIncremental = true;
        }

        static void BuildScene(GameAssets ga)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(ScenePath));
            var scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            var go = new GameObject("Game");
            var b = go.AddComponent<Bootstrap>();
            b.assets = ga;
            EditorSceneManager.SaveScene(scene, ScenePath);
            EditorBuildSettings.scenes = new[] { new EditorBuildSettingsScene(ScenePath, true) };
        }

        public static void BuildDev() { Build("Builds/Dev/CASCADE.exe", BuildOptions.Development); }
        public static void BuildRelease() { Build("Builds/CASCADE/CASCADE.exe", BuildOptions.None); }

        static void Build(string exe, BuildOptions opts)
        {
            try
            {
                RebuildAllQuiet();
                var o = new BuildPlayerOptions
                {
                    scenes = new[] { ScenePath },
                    locationPathName = exe,
                    target = BuildTarget.StandaloneWindows64,
                    options = opts
                };
                BuildReport r = BuildPipeline.BuildPlayer(o);
                var s = r.summary;
                Debug.Log("BUILD_RESULT " + s.result + " errors " + s.totalErrors + " warnings " + s.totalWarnings + " size " + (s.totalSize / (1024 * 1024)) + " MB time " + s.totalTime);
                if (s.result != BuildResult.Succeeded)
                {
                    Debug.LogError("CASCADE_FAIL build " + exe);
                    if (Application.isBatchMode) EditorApplication.Exit(1);
                }
                else Debug.Log("CASCADE_OK build " + exe);
            }
            catch (System.Exception e)
            {
                Debug.LogError("CASCADE_FAIL build: " + e);
                if (Application.isBatchMode) EditorApplication.Exit(1);
            }
        }

        static void RebuildAllQuiet()
        {
            HdrpSetup.Run();
            ConfigurePlayer();
            var ga = AssetFactory.BuildAll();
            if (AssetFactory.CheckShaders() > 0) throw new System.Exception("shader compile errors");
            BuildScene(ga);
            AssetDatabase.SaveAssets();
        }

        /// <summary>Prints path and terrain facts to the log (no GPU).</summary>
        public static void Probe()
        {
            PathDef.Build();
            WorldGen.Build();
            Debug.Log("CASCADE_INFO path length " + PathDef.Length + " quayEnd " + PathDef.SQuayEnd + " narrow " + PathDef.SNarrowStart + " stairEnd " + PathDef.SStairEnd + " promEnd " + PathDef.SPromEnd);
            for (float s = 0f; s <= PathDef.Length; s += 100f)
            {
                Vector3 p = PathDef.Pos(s);
                Debug.Log("CASCADE_INFO s " + s + " pos " + p + " ground " + WorldGen.Height(p.x, p.z).ToString("F2") + " sd " + WorldGen.SdInner(p.x, p.z).ToString("F1"));
            }
            Debug.Log("CASCADE_OK Probe");
        }
    }
}
